from typing import Any

from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int


class CustomerInsightsController:
    def __init__(self, orders: OrderService) -> None:
        self._orders = orders

    def handle_order_history(self, customer_id: str) -> Response:
        """A customer's orders, newest first, with the same totals as the order summary."""
        try:
            summaries = self._orders.order_history(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        orders: list[dict[str, Any]] = [
            {"order_id": s.order.order_id, "status": s.order.status, "total_cents": s.total_cents}
            for s in summaries
        ]
        return Response(200, {"customer_id": customer_id, "orders": orders})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Count and total of the customer's orders that are not cancelled, at order-summary totals."""
        try:
            summaries = self._orders.active_order_summaries(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {
            "customer_id": customer_id,
            "order_count": len(summaries),
            "lifetime_value_cents": sum(s.total_cents for s in summaries),
        })

def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_order_history_unknown_customer_is_404(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_order_history_empty_for_customer_without_orders(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_order_history_is_newest_first_and_includes_cancelled(shop):
    first = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    second = order(shop, "c1", ("PEN", 2)).body["order_id"]
    third = order(shop, "c1", ("LAMP", 1)).body["order_id"]
    shop.orders.handle_cancel(second)

    response = shop.insights.handle_order_history("c1")

    assert response.status == 200
    assert response.body == {
        "customer_id": "c1",
        "orders": [
            {"order_id": third, "status": "placed", "total_cents": 6_000},
            {"order_id": second, "status": "cancelled", "total_cents": 600},
            {"order_id": first, "status": "placed", "total_cents": 2_500},
        ],
    }


def test_order_history_totals_match_order_summary_including_discount(shop):
    # c2 is gold tier, so the discount applies to its orders.
    placed = order(shop, "c2", ("BOOK", 4), ("LAMP", 2)).body["order_id"]
    order_summary_total = shop.orders.handle_get(placed).body["total_cents"]

    history = shop.insights.handle_order_history("c2").body["orders"]

    assert history == [{"order_id": placed, "status": "placed", "total_cents": order_summary_total}]


def test_lifetime_value_unknown_customer_is_404(shop):
    response = shop.insights.handle_lifetime_value("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_lifetime_value_with_no_orders_is_zero(shop):
    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_excludes_cancelled_orders(shop):
    order(shop, "c1", ("BOOK", 1))            # 2_500
    cancelled = order(shop, "c1", ("PEN", 2)).body["order_id"]  # 600, cancelled
    shop.orders.handle_cancel(cancelled)
    order(shop, "c1", ("LAMP", 1))            # 6_000

    response = shop.insights.handle_lifetime_value("c1")

    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 2, "lifetime_value_cents": 8_500}


def test_lifetime_value_uses_order_summary_totals_including_discount(shop):
    # c2 is gold tier; 4 * 2_500 + 2 * 6_000 = 22_000 gets 15% off -> 18_700.
    placed = order(shop, "c2", ("BOOK", 4), ("LAMP", 2)).body["order_id"]
    order_summary_total = shop.orders.handle_get(placed).body["total_cents"]

    response = shop.insights.handle_lifetime_value("c2")

    assert response.body == {"customer_id": "c2", "order_count": 1,
                             "lifetime_value_cents": order_summary_total}
    assert order_summary_total == 18_700


def test_order_history_only_contains_the_requested_customers_orders(shop):
    order(shop, "c1", ("BOOK", 1))
    mine = order(shop, "c2", ("PEN", 1)).body["order_id"]

    history = shop.insights.handle_order_history("c2").body["orders"]

    assert [o["order_id"] for o in history] == [mine]

